using namespace boost::asio::experimental::awaitable_operators;
awaitable<Reply> call(tcp::socket& s, Request req) {
  steady_timer t(s.get_executor(), std::chrono::seconds(5));
  auto r = co_await (
      async_call(s, req, use_awaitable) ||
      t.async_wait(use_awaitable));
  if (r.index() == 1) throw Timeout{};   // timer won; request cancelled
  co_return std::get<0>(r);
}

grpc::ClientContext ctx;
ctx.set_deadline(std::chrono::system_clock::now() + std::chrono::seconds(5));
QuoteRequest req; req.set_symbol("ACME");
QuoteReply reply;
grpc::Status st = stub->GetQuote(&ctx, req, &reply);
if (st.error_code() == grpc::StatusCode::DEADLINE_EXCEEDED) return Err::Timeout;
if (!st.ok()) return Err::Remote(st.error_message());
return Ok(reply);
